#!/usr/bin/env python3
"""Google Doc builder library — create/edit docs with headings, bullets,
auto-numbered lists, and native tables via the Docs API (OAuth-as-user).

Element helpers (build a list, then DocBuilder.render(doc_id, elements)):
    H1("Title")          heading 1
    H2("Section")        heading 2
    P("text")            normal paragraph
    B("bullet")          disc bullet (BULLET_DISC_CIRCLE_SQUARE)
    N("step")            AUTO-numbered item (NUMBERED_DECIMAL_NESTED);
                         nest with leading tabs: N("\\tsub-step")
    T([[hdr...], [row...]])  native table; row 0 = bold header

Key implementation detail: tables shift every index after them, so each table is
inserted, then the doc is RE-FETCHED and cells are filled bottom-up (descending
start index) so earlier indices stay valid. The running end index is re-fetched
after every table.

Run as a script for a smoke-test demo:  python3 gdoc_builder.py "Demo Doc Title"
"""

import sys

from googleapiclient.discovery import build

from gdoc_auth import get_credentials


def H1(t):
    return {"kind": "text", "text": t, "style": "HEADING_1"}


def H2(t):
    return {"kind": "text", "text": t, "style": "HEADING_2"}


def P(t):
    return {"kind": "text", "text": t, "style": "NORMAL_TEXT"}


def B(t):
    return {"kind": "text", "text": t, "style": "NORMAL_TEXT",
            "bullet": "BULLET_DISC_CIRCLE_SQUARE"}


def N(t):
    return {"kind": "text", "text": t, "style": "NORMAL_TEXT",
            "bullet": "NUMBERED_DECIMAL_NESTED"}


def T(rows):
    return {"kind": "table", "rows": rows}


class DocBuilder:
    def __init__(self, creds=None):
        creds = creds or get_credentials()
        self.docs = build("docs", "v1", credentials=creds)
        self.drive = build("drive", "v3", credentials=creds)

    # ---------- Drive ----------

    def create(self, title):
        """Create an empty Google Doc, return its id (owned by the OAuth user)."""
        f = self.drive.files().create(
            body={"name": title, "mimeType": "application/vnd.google-apps.document"},
            fields="id",
        ).execute()
        return f["id"]

    @staticmethod
    def url(doc_id):
        return f"https://docs.google.com/document/d/{doc_id}/edit"

    # ---------- Docs ----------

    def _end_index(self, doc_id):
        doc = self.docs.documents().get(fields="body(content(endIndex))",
                                        documentId=doc_id).execute()
        return doc["body"]["content"][-1]["endIndex"] - 1

    def _batch(self, doc_id, requests):
        if requests:
            self.docs.documents().batchUpdate(
                documentId=doc_id, body={"requests": requests}).execute()

    def clear(self, doc_id):
        """Delete the whole body (works across tables) — then re-render."""
        end = self._end_index(doc_id)
        if end > 1:
            self._batch(doc_id, [{"deleteContentRange":
                                  {"range": {"startIndex": 1, "endIndex": end}}}])

    def render(self, doc_id, elements):
        """Append elements at the end of the doc, in order."""
        for el in elements:
            if el["kind"] == "table":
                self._insert_table(doc_id, el["rows"])
            else:
                self._insert_text(doc_id, el)

    def _insert_text(self, doc_id, el):
        idx = self._end_index(doc_id)
        text = el["text"] + "\n"
        rng = {"startIndex": idx, "endIndex": idx + len(text) - 1}
        reqs = [
            {"insertText": {"location": {"index": idx}, "text": text}},
            {"updateParagraphStyle": {
                "range": rng,
                "paragraphStyle": {"namedStyleType": el["style"]},
                "fields": "namedStyleType"}},
        ]
        if el.get("bullet"):
            reqs.append({"createParagraphBullets":
                         {"range": rng, "bulletPreset": el["bullet"]}})
        self._batch(doc_id, reqs)

    def _insert_table(self, doc_id, rows):
        n_rows, n_cols = len(rows), max(len(r) for r in rows)
        insert_idx = self._end_index(doc_id)
        self._batch(doc_id, [{"insertTable": {
            "rows": n_rows, "columns": n_cols,
            "location": {"index": insert_idx}}}])

        # Re-fetch: insertTable shifted all indices after insert_idx.
        doc = self.docs.documents().get(documentId=doc_id).execute()
        table = next(e for e in doc["body"]["content"]
                     if "table" in e and e["startIndex"] >= insert_idx)

        # Collect (cell_start_index, text) for every cell, fill BOTTOM-UP so
        # earlier indices stay valid while inserting.
        cells = []
        for r, row_el in enumerate(table["table"]["tableRows"]):
            for c, cell in enumerate(row_el["tableCells"]):
                text = rows[r][c] if c < len(rows[r]) else ""
                start = cell["content"][0]["startIndex"]
                cells.append((start, str(text)))
        reqs = [{"insertText": {"location": {"index": start}, "text": text}}
                for start, text in sorted(cells, key=lambda x: -x[0]) if text]
        self._batch(doc_id, reqs)

        # Bold the header row (re-fetch again: cell fills shifted indices).
        doc = self.docs.documents().get(documentId=doc_id).execute()
        table = next(e for e in doc["body"]["content"]
                     if "table" in e and e["startIndex"] >= insert_idx)
        header = table["table"]["tableRows"][0]
        reqs = []
        for cell in header["tableCells"]:
            for para in cell["content"]:
                if para["endIndex"] - para["startIndex"] > 1:
                    reqs.append({"updateTextStyle": {
                        "range": {"startIndex": para["startIndex"],
                                  "endIndex": para["endIndex"] - 1},
                        "textStyle": {"bold": True}, "fields": "bold"}})
        self._batch(doc_id, reqs)

    # ---------- Review notes ----------

    def find_red_text(self, doc_id):
        """Return red-text runs (client review notes) as [(text, startIndex)]."""
        doc = self.docs.documents().get(documentId=doc_id).execute()
        notes = []

        def scan(content):
            for el in content:
                if "paragraph" in el:
                    for run in el["paragraph"].get("elements", []):
                        tr = run.get("textRun")
                        if not tr:
                            continue
                        rgb = (tr.get("textStyle", {}).get("foregroundColor", {})
                               .get("color", {}).get("rgbColor", {}))
                        if (rgb.get("red", 0) >= 0.5
                                and rgb.get("green", 0) <= 0.45
                                and rgb.get("blue", 0) <= 0.45):
                            notes.append((tr["content"].strip(), run["startIndex"]))
                elif "table" in el:
                    for row in el["table"]["tableRows"]:
                        for cell in row["tableCells"]:
                            scan(cell["content"])

        scan(doc["body"]["content"])
        return notes


if __name__ == "__main__":
    title = sys.argv[1] if len(sys.argv) > 1 else "gdoc_builder smoke test"
    b = DocBuilder()
    doc_id = b.create(title)
    b.render(doc_id, [
        H1(title),
        P("Created by gdoc_builder.py as a smoke test."),
        H2("Checklist"),
        B("OAuth token valid"),
        B("Table fill bottom-up"),
        N("First auto-numbered step"),
        N("\tNested sub-step"),
        N("Second step"),
        T([["Field", "Value"], ["Owner", "OAuth user"], ["API", "Docs v1"]]),
    ])
    print(b.url(doc_id))

